const r = await tools.exec_command({
  cmd: "nvidia-smi --id=1 --query-gpu=index,uuid,memory.used,memory.total,utilization.gpu --format=csv,noheader; nvidia-smi --query-compute-apps=gpu_uuid,pid,process_name,used_memory --format=csv,noheader | rg 'GPU-a3ba221d-3832-3906-cef7-f8aae054c149' || true; ps -eo pid,ppid,pgid,args --sort=pid | rg 'official_track1_eval|run_track1_formal_p0_score_worker' || true",
  workdir: "/data/fjy/worldarena",
  yield_time_ms: 10000,
  max_output_tokens: 15000,
  sandbox_permissions: "require_escalated",
